    LANGUAGE_WRAPPER = 'Let {n} be a fixed positive integer with {n} >= 6. For any non-empty finite subset S of {1,2,...,{n}}, define the weighted mean f_w(S) = (sum_{x in S} x^2) / (sum_{x in S} x). Consider all ordered pairs (A, B) of disjoint non-empty subsets with A ∪ B = {1, 2, ..., {n}}, 1 ≤ |A| ≤ {n}-2, and 2 ≤ |B| ≤ {n}-1. For any p in B, define A_p = A ∪ {p} and B_p = B \\ {p}. Over all choices of (A, B) satisfying the conditions and all p in B, determine the maximum possible value of (f_w(A_p) − f_w(A)) · (f_w(B_p) − f_w(B)). If the maximum can be expressed as an irreducible fraction u/v, report u + v.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

