# Try to find an n that yields a non-trivial (positive) maximum quickly.
# We will sample n in a moderate range to keep verifier work reasonable.
def compute_max_for_n(n):
    # Compute maximum assuming the extremal contiguous split heuristic (proved in notes)
    # A = {1,...,m}, B = {m+1,...,n}, scanning m and p.
    S1_total = n*(n+1)//2
    S2_total = n*(n+1)*(2*n+1)//6
    best_num = None
    best_den = None
    for m in range(1, n-1):
        # ensure B has at least 2 elements
        if n - m < 2:
            continue
        S1_A = m*(m+1)//2
        S2_A = m*(m+1)*(2*m+1)//6
        S1_B = S1_total - S1_A
        S2_B = S2_total - S2_A
        # p in B: m+1..n
        for p in range(m+1, n+1):
            # dfA = p/(S1_A + p) * (p - S2_A/S1_A)
            # dfB = p/(S1_B - p) * (S2_B/S1_B - p)
            # Product as exact rational:
            num = p*p * (p*S1_A - S2_A) * (S2_B - p*S1_B)
            den = (S1_A + p) * S1_A * (S1_B - p) * S1_B
            if den <= 0:
                continue
            if best_num is None:
                best_num, best_den = num, den
            else:
                # compare num/den vs best_num/best_den
                left = num * best_den
                right = best_num * den
                if left > right:
                    best_num, best_den = num, den
    return best_num, best_den
